#!/usr/bin/env python3
"""Close L14 source-to-question challenge after independent valid dispositions."""
import collections,contextlib,datetime,hashlib,io,json,sys
from pathlib import Path
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'scripts'))
import assemble_bank
from validate import question_hash,validate_bank
load=lambda p:json.loads((R/p).read_text())
lecture=next(x for x in load('sources/lecture_map.json') if x['id']=='L14')
assert (lecture['startPage'],lecture['endPage'])==(428,449)
captured={};assemble_bank.dump=lambda p,v:captured.setdefault(str(p),v);sys.argv=['assemble_bank.py']
with contextlib.redirect_stdout(io.StringIO()):assemble_bank.main()
bank=next(v for k,v in captured.items() if k.endswith('/data/bank.json'))
valid=validate_bank(bank,R);qs=[q for q in bank['questions'] if q.get('lectureId')=='L14'];assert len(qs)==55
valid['L14Statuses']=dict(collections.Counter(q['status'] for q in qs));valid['L13Statuses']=dict(collections.Counter(q['status'] for q in bank['questions'] if q.get('lectureId')=='L13'))
assert valid['valid'] and not valid['errors'];assert valid['L14Statuses']=={'verified':55};assert valid['L13Statuses']=={'verified':48}
(R/'audits/W03-L14-v2-independent-validation.json').write_text(json.dumps(valid,ensure_ascii=False,indent=2)+'\n')
initial=load('audits/blind-answers-W03-L14-independent.json')
notes={
428:['Title, course identity, author and campus illustration. No independent technical proposition.'],
429:['Learning objectives identify Lagrangian manipulator dynamics and worked examples; roadmap rather than new exposition.'],
430:['Contents outline energy basics, Euler–Lagrange modelling and examples; roadmap rather than additional testable derivation.'],
431:['Newton–Euler uses linkwise free-body force/torque balances and recursive calculation. Lagrangian modelling uses scalar energies and independent coordinates, eliminating ideal constraint reactions already incorporated by those coordinates.','The two approaches yield the same equations for a common model and conventions; stated realtime/analytical preferences are not universal runtime guarantees.','Model-based control and AI-driven dynamics learning are stated applications, not guarantees of fitted parameters, complete loads or validated predictions.'],
432:['Translational kinetic energy is one-half mass times speed squared; fixed-axis rotational energy is one-half inertia times squared angular speed.','Net work changes kinetic energy: accelerating from rest adds energy, whereas stopping entails negative work on the body and positive mechanical energy removed.'],
433:['Conservative potential is the force line integral from the current position to a reference; reversing integration limits changes the sign.','Total mechanical energy K+U differs from the later Lagrangian K−U; potential requires appropriate conservative-force scope.'],
434:['L=K−U with generalized coordinates and coordinate rates; Euler–Lagrange produces generalized applied force/torque.','Rayleigh potential is the named dissipative extension in this presentation. Its blanket gyroscopic/circulatory limitation is a source-attributed assertion, not endorsed as a universal theorem about extended formulations.'],
435:['Rigid-link kinetic energy is COM translational energy plus the inertia-tensor angular quadratic form; angular components and tensor must share a basis.','Total kinetic energy sums both contributions over all links.'],
436:['Gravitational potential is −m g0 dot pCOM plus a constant reference, with force-vector and height signs consistent.','Summing link potentials gives total U; constant reference shifts disappear from effort equations.'],
437:['Substituting K−U into Euler–Lagrange gives d(K_qdot)/dt−K_q+U_q when U has no rate dependence.','Generalized forces are work-conjugate to the coordinates; the generic torque notation must not turn a prismatic force into a torque.'],
438:['Minimal independent coordinate count equals DOF count. Joint angles and prismatic displacements may coexist.','Generalized velocities are coordinate time derivatives, not necessarily end-effector Cartesian velocity; mixed effort and rate units preserve power.'],
439:['The massless single arm has a tip mass, a zero-angle undeflected torsional spring, rightward X and downward Y; theta is downward-positive.','Tip downward coordinate is l sin(theta), so gravitational U is negative with downward displacement. Spring energy is one-half kt theta squared and physical restoring torque is −kt theta.','K is one-half m l squared times angular rate squared. Energy and power consequences require the stated undamped assumptions.'],
440:['Compute K_qdot, its time derivative, K_q and U_q before assembling ml² angular acceleration+kt theta−mgl cos(theta)=tau.','The displayed final zero on the RHS is only the unforced specialization. The driven equation, rest acceleration, equilibrium, radian spring torque, energy-power identity and zero-gravity natural frequency are covered by separate appropriate applications.'],
441:['The force moment lever-arm complement gives sin(pi/2−theta)=cos(theta) for radian theta; physical gravity assists positive downward motion near horizontal.','Newton force/moment balance agrees with Lagrange for the same signs and unforced specialization. Gravity plus spring is not the total moment if applied actuator torque is present.'],
442:['The RP figure defines first COM radius l1 and second COM radius d2 measured from the base revolute axis, not merely exposed slider length.','Both links inherit the same out-of-plane angular speed despite the prismatic second joint. Diagonal COM tensors therefore select Izz1 and Izz2. Radial and tangential velocities are orthogonal.'],
443:['Link kinetic energies combine first-link COM translation, both COM spin energies, second-link tangential translation and radial translation.','A=m1 l1²+Izz1+Izz2+m2 d2² is the rotational kinetic coefficient, producing diagonal M without eliminating velocity coupling.','First potential m1 l1 g(sin(theta1)+1) encodes upward-positive angle and an additive datum.'],
444:['Second potential is m2 g d2 sin(theta1)+m2 g d2max with d2max constant; total potential and zero reference are accounted for.','Differentiate K and U with coordinates and rates as independent arguments; preserve coordinate ordering in all vectors. K_qdot is generalized momentum, not acceleration or energy.'],
445:['Total time differentiation of A(d2) thetadot requires the product rule, including 2m2 d2 d2dot thetadot.','Euler–Lagrange assembly retains radial centripetal effort and gravity; conservation of angular generalized momentum at zero gravity/revolute torque allows work from the radial actuator.'],
446:['Final revolute and radial efforts decompose into M qddot+V+G. Their mixed units, velocity-product signs, inertial coupling despite diagonal M, static gravity limits, radial support force and mechanical power are covered.','The lower standalone M glyph before m2 d2² is unclear; Q040 locally qualifies it using positive kinetic energy and clear upper equations, bound to source hash. The page is not globally marked corrected.','The velocity effort power identity qdot dot V=one-half qdot dot Mdot qdot independently checks the product-rule coefficient and radial sign.'],
447:['Summary repeats energy-based dynamics and the manipulator effort decomposition; V used for scalar potential versus velocity-product effort must be distinguished by context.','Workflow and conservative-load scope are covered; repetition does not require duplicate questions.'],
448:['Bibliographic references only. Cited external books are not additional assigned-slide factual content for automatic question generation.'],
449:['Closing thanks and branding only.']}
pages=[]
for n in range(428,450):
 covered=[q['id'] for q in qs if any(c['physicalPage']==n for c in q['citations'])]
 excluded=n in [428,429,430,448,449]
 assert covered or excluded
 preview=R/f'sources/previews/lectures/page-{n:04d}.webp'
 pages.append({'physicalPage':n,'printedSlideNumber':str(n-427),'week':3,'lectureId':'L14','lectureRelativePage':n-427,'previewPath':str(preview.relative_to(R)),'previewSha256':hashlib.sha256(preview.read_bytes()).hexdigest(),'width':1800,'height':1013,'method':'rendered_page_and_extracted_text','inspectionBasis':'Initial source-first inspection before keyed access; targeted revision/gap source pages reinspected at 17:32 UTC.','observations':notes[n],'meaningfulAngles':[] if excluded else notes[n],'disposition':'excluded_administrative_or_references' if excluded else 'covered_by_current_verified_questions','questionCoverage':covered,'coverageStatus':'excluded_with_reason' if excluded else 'covered','exclusionReason':'Title/objectives/contents, bibliography or closing thanks with no new technical exposition.' if excluded else None})
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
out={'reviewerId':'build_offline_study_interface-L14-independent','sourceId':'lectures','sourceSha256':'2dcca11fda764949d36f6f174bd72ccc2a83c2863f522635e7afd8539d88f84c','completedAt':now,'status':'completed_with_all_current_items_verified','scope':{'week':3,'lectureId':'L14','physicalPages':[428,449],'pageCount':22,'method':'Actual readable pixels and full extracted text inspected before initial keyed review. Original source-derived answers were frozen independently; revision reviews retain prior exposure labels. This challenge now maps every source page and meaningful angle to current accepted versions or an explicit exclusion.'},'pages':pages,'all22PagesAccountable':True,'remainingMeaningfulOmissions':0,'remainingCurrentQuestionQualityFlags':0,'coverageClosed':True,'closureScope':'L14 source-to-question omission and question-quality challenge only. Source caveats remain visible. Not a claim of app, assignments, later lectures or whole-project completion.','currentQuestionCount':55,'currentReviewBindings':[{'questionId':q['id'],'questionVersion':q['version'],'questionSha256':question_hash(q),'reviewIds':q['reviewIds']} for q in qs],'gapClosures':[{'physicalPage':432,'questionIds':['W03-L14-GAP-Q001'],'basis':'Negative net stopping work versus positive energy removed is directly tested, rather than only kinetic-energy evaluation.'},{'physicalPage':431,'questionIds':['W03-L14-GAP-Q002'],'basis':'The stated model-based/AI-learning use is tested without unsupported guarantees.'}],'sourceConflictsPreserved':['Broad gyroscopic/circulatory limitation is source-attributed only.','Single-joint zero RHS is explicitly the tau=0 specialization.','The lower p446 mass-matrix glyph remains a local source ambiguity; valid energy and upper equations establish the tested coefficient.','Summary V notation is context-dependent; scalar potential and velocity-effort vector are distinct.'],'basisArtifacts':['audits/blind-answers-W03-L14-independent.json','audits/W03-L14-independent-summary.json','audits/blind-answers-W03-L14-v2-independent.json','audits/W03-L14-v2-independent-summary.json','audits/W03-L14-v2-independent-validation.json'],'independentComputationCases':2218,'notes':['The authoritative lecture map confirms 22 pages, not 23; physical page450 is L15.','No author questions, inspection records, source ledgers, canonical bank or Git state were changed.']}
p=R/'audits/W03-L14-coverage-challenge-closure-independent.json';assert not p.exists();p.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'valid':valid['valid'],'errors':valid['errors'],'L13':valid['L13Statuses'],'L14':valid['L14Statuses'],'pagesAccounted':len(pages),'coverageClosed':True},indent=2))
